import{_ as a,o as r,c as t,ae as l}from"./chunks/framework.A5CuatG_.js";const c=JSON.parse('{"title":"订阅节点","description":"","frontmatter":{},"headers":[],"relativePath":"clash-intro.md","filePath":"clash-intro.md"}'),i={name:"clash-intro.md"};function o(s,e,n,h,f,p){return r(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="订阅节点" tabindex="-1">订阅节点 <a class="header-anchor" href="#订阅节点" aria-label="Permalink to &quot;订阅节点&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>本教程中提到的C*l*a*s*h、“小火箭” 等仅是工具软件，本身并不提供代理服务，需要配合节点订阅才能正常使用。下面将介绍如何购买并配置C*l*a*s*h节点订阅，以及使用C*l*a*s*h进行科学**<br> 首先要购买机场节点，市面上很多所谓的“加速器”通常是按每月、每季或者每年扣费，而且不一定能保证一直可用。这里推荐按量付费的服务商，不用每月/季/年交钱。</p><p>注册购买链接推荐：</p><ul><li><a href="https://hasucn.me/i/k0jeNPK0" target="_blank" rel="noreferrer">永雏塔菲</a>(最低充值5元)</li><li><a href="https://mojie.co/register?aff=MGG2FBWd" target="_blank" rel="noreferrer">mojie</a>(19.9元130G，可1元试用)</li><li><a href="https://mojie.app/register?aff=MGG2FBWd" target="_blank" rel="noreferrer">mojie(备用地址1)</a></li><li><a href="https://mojie.kim/register?aff=MGG2FBWd" target="_blank" rel="noreferrer">mojie(备用地址2)</a></li><li><a href="http://mojie.host/register?aff=MGG2FBWd" target="_blank" rel="noreferrer">mojie(备用地址3)</a></li></ul><p>按量计费与其它的包月套餐不一样，如果是包月套餐，当套餐到期后，套餐中剩余的流量都会失效，白白浪费掉了，而按量付费则没有到期失效的概念，你购买的流量将会一直存在，不会产生用不完的流量浪费的情况，账户内的流量不会过期，永久有效。</p><p><a href="/clash.html">下一节：C*l*a*s*h 安装和使用</a></p>',7)])])}const m=a(i,[["render",o]]);export{c as __pageData,m as default};
